// Generated by esquadro: do not edit. A number on the dashboard, with what
// it is about, and a chart of a report's rows, with shadcn/ui's Card and
// Chart.
import type { ReactNode } from "react"
import { Bar, BarChart, CartesianGrid, XAxis } from "recharts"
import { Card, CardDescription, CardFooter, CardHeader, CardTitle, CardContent } from "@/components/ui/card"
import { ChartContainer, ChartTooltip, ChartTooltipContent } from "@/components/ui/chart"
import type { ChartConfig } from "@/components/ui/chart"

export function StatCard({ label, value, hint }: { label: string; value: ReactNode; hint?: ReactNode }) {
  return (
    <Card className="@container/card">
      <CardHeader>
        <CardDescription>{label}</CardDescription>
        <CardTitle className="text-2xl font-semibold tabular-nums @[250px]/card:text-3xl">{value}</CardTitle>
      </CardHeader>
      {hint && <CardFooter className="text-sm text-muted-foreground">{hint}</CardFooter>}
    </Card>
  )
}

/** Bars of rows: x, the name of each; y, the number. */
export function BarsChart<T extends Record<string, unknown>>({
  title,
  rows,
  x,
  y,
  label,
}: {
  title?: string
  rows: T[]
  x: keyof T & string
  y: keyof T & string
  label?: string
}) {
  const config = { [y]: { label: label ?? y, color: "var(--chart-1)" } } satisfies ChartConfig
  return (
    <Card>
      {title && (
        <CardHeader>
          <CardTitle>{title}</CardTitle>
        </CardHeader>
      )}
      <CardContent>
        <ChartContainer config={config} className="aspect-auto h-64 w-full">
          <BarChart data={rows} accessibilityLayer>
            <CartesianGrid vertical={false} />
            <XAxis dataKey={x as never} tickLine={false} axisLine={false} tickMargin={8} />
            <ChartTooltip content={<ChartTooltipContent />} />
            <Bar dataKey={y as never} fill={`var(--color-${y})`} radius={4} />
          </BarChart>
        </ChartContainer>
      </CardContent>
    </Card>
  )
}
